// Combine base products with updated specs and official ABC Curve items
export const INITIAL_PRODUCTS: ProductCatalogItem[] = (() => {
  const map = new Map<string, ProductCatalogItem>();
  
  // 1. Index all base products by SKU code
  INITIAL_PRODUCTS_BASE.forEach(p => {
    map.set(p.code, { ...p });
  });

  // 2. Apply updated product specifications (pallet factor, lastro factor, hectoliter factor, price, shelf life)
  UPDATED_PRODUCT_SPECS.forEach(spec => {
    const existing = map.get(spec.code);
    const factorSKU = existing?.factorSKU || (spec.description.includes('C/12') || spec.description.includes('C 12') || spec.description.includes('CX12') || spec.description.includes('SH C/12') || spec.description.includes('SH C12') ? 12 : spec.description.includes('C/6') || spec.description.includes('CX 6') || spec.description.includes('C/06') || spec.description.includes('SH C/6') ? 6 : spec.description.includes('C/24') || spec.description.includes('CX 24') ? 24 : spec.description.includes('C/23') || spec.description.includes('CX C/23') ? 23 : spec.description.includes('C/40') || spec.description.includes('CX40') ? 40 : 12);
    const unitPrice = Number((spec.price / (factorSKU || 1)).toFixed(2));

    if (existing) {
      map.set(spec.code, {
        ...existing,
        description: spec.description,
        palletFactor: spec.palletFactor,
        lastroFactor: spec.lastroFactor,
        price: spec.price,
        unitPrice: unitPrice > 0 ? unitPrice : existing.unitPrice,
        hectoliterFactor: spec.hectoliterFactor,
        defaultShelfLifeDays: spec.defaultShelfLifeDays > 0 ? spec.defaultShelfLifeDays : (existing.defaultShelfLifeDays || 180),
        factorSKU: factorSKU
      });
    } else {
      map.set(spec.code, {
        code: spec.code,
        description: spec.description,
        unit: 'cx12',
        category: spec.description.includes('PET') || spec.description.includes('LATA') || spec.description.includes('LT') || spec.description.includes('600ML') || spec.description.includes('1L') ? 'Bebidas' : 'Geral',
        price: spec.price,
        unitPrice: unitPrice,
        hectoliterFactor: spec.hectoliterFactor,
        palletFactor: spec.palletFactor,
        lastroFactor: spec.lastroFactor,
        factorSKU: factorSKU,
        packaging: 'PADRÃO',
        abcClass: 'C',
        rank: 999,
        defaultShelfLifeDays: spec.defaultShelfLifeDays > 0 ? spec.defaultShelfLifeDays : 180
      });
    }
  });

  // 3. Apply and prioritize the Official ABC items to strictly preserve Curva ABC and Rank
  OFFICIAL_ABC_CURVE_ITEMS.forEach((official) => {
    const existing = map.get(official.code);
    if (existing) {
      map.set(official.code, {
        ...existing,
        abcClass: official.abcClass,
        rank: official.rank
      });
    }
  });

  // Sort by official rank
  return Array.from(map.values()).sort((a, b) => (a.rank || 999) - (b.rank || 999));
})();

